    multibandFdn_.forEachTank ([&](FDNReverb& tk){ tk.setModRate (hz); });
    spring_.setModRate (hz);
    nonLinear_.setModRate (hz);
    shimmer_.setModRate (hz);       // hijacked → FEEDBACK (0.1..10 Hz → 0..0.95 cascade gain)
