// ============================================================================
// ReverseRoomEngine — causal rising-ER onset + dark modulated FDN tail.
// Reverse-engineered from ref-reverse-1 (reference "Reverse 1" program).
// See header for the full architecture and the measured reference spec.
// ============================================================================

void ReverseRoomEngine::prepare (double sampleRate, int maxBlockSize)
{
    sampleRate_ = sampleRate;
    maxBlock_   = maxBlockSize;

    // Tuning sweep override (init thread only — NEVER in process()). No-op when
    // unset → shipping renders use the hard-coded defaults (bit-null/determinism
    // preserved). Format: "rampMs,slope,floorGain,threshDB,holdMs,closeTauMs".
    if (const char* ov = std::getenv ("DUSKVERB_REVERSE"))
    {
        float rm = rampMs_, sl = slope_, fg = floorGain_, thDb = -60.0f,
              hm = holdMs_, ct = closeTauMs_, ow = onsetWindowMs_;
        if (std::sscanf (ov, "%f,%f,%f,%f,%f,%f,%f", &rm, &sl, &fg, &thDb, &hm, &ct, &ow) >= 1)
        {
            rampMs_        = std::clamp (rm, 5.0f, 1000.0f);
            slope_         = std::clamp (sl, 0.1f, 4.0f);
            floorGain_     = std::clamp (fg, 0.0f, 1.0f);
            threshLin_     = std::pow (10.0f, std::clamp (thDb, -120.0f, 0.0f) / 20.0f);
            holdMs_        = std::clamp (hm, 0.0f, 4000.0f);
            closeTauMs_    = std::clamp (ct, 0.5f, 200.0f);
            onsetWindowMs_ = std::clamp (ow, 0.0f, 4000.0f);
        }
    }

    // Velvet-noise FIR tail (replaces the FDN — see VelvetTail.h). Baked defaults
    // = the ref-reverse-1 per-band T60 / level / stereo; DUSKVERB_VELVET overrides
    // for hand-tuning without a rebuild. Feed-forward → no FDN mid-decay floor.
    velvet_.prepare (sampleRate, maxBlockSize);

    // ER ring buffers: must hold the longest tap delay (= rampMs_ at the
    // largest size scale ~1.6x) -> size generously to pow2.
    const int maxRampSamp = static_cast<int> (rampMs_ * 0.001 * sampleRate * 2.5) + 64;
    const int ringSize    = DspUtils::nextPowerOf2 (std::max (maxRampSamp, 1024));
    erL_.ring.assign (static_cast<size_t> (ringSize), 0.0f);
    erR_.ring.assign (static_cast<size_t> (ringSize), 0.0f);
    erL_.mask = erR_.mask = ringSize - 1;
    erL_.writePos = erR_.writePos = 0;

    erBufL_.assign (static_cast<size_t> (maxBlockSize), 0.0f);
    erBufR_.assign (static_cast<size_t> (maxBlockSize), 0.0f);

    // Gate coeffs — recomputed every prepare (track sample-rate changes).
    // One-pole: y += coeff*(target-y), coeff = 1 - exp(-1/(tau*sr)).
    auto onePole = [sr = sampleRate] (double tauSec) -> float
        { return static_cast<float> (1.0 - std::exp (-1.0 / (tauSec * sr))); };
    envAtkCoeff_    = onePole (0.0015);              // 1.5 ms attack (track body)
    envRelCoeff_    = onePole (0.080);               // 80 ms release (< holdMs, no chatter)
    gateOpenCoeff_  = onePole (0.006);               // ~6 ms open (doesn't reshape the FIR swell)
    gateCloseCoeff_ = onePole (closeTauMs_ * 0.001); // close tau → hard cliff, continuous gain
    holdSamples_    = std::max (1, static_cast<int> (holdMs_ * 0.001 * sampleRate));
    holdMaxSamps_   = std::max (holdSamples_, static_cast<int> (holdMaxMs_ * 0.001 * sampleRate));
    onsetWindowSamps_ = static_cast<int> (onsetWindowMs_ * 0.001 * sampleRate);   // 0 = disabled

    rebuildTaps();
    clearBuffers();   // reset gate state + velvet running/biquad state across a
                      // re-prepare (sample-rate / block-size change) — prepare()
                      // alone left gateState_/gateGain_/envFollow_ + velvet crossover
                      // history stale (only clearBuffers() resets them).
    prepared_ = true;
}

void ReverseRoomEngine::clearBuffers()
{
    velvet_.clear();
    std::fill (erL_.ring.begin(), erL_.ring.end(), 0.0f);
    std::fill (erR_.ring.begin(), erR_.ring.end(), 0.0f);
    erL_.writePos = erR_.writePos = 0;
    std::fill (erBufL_.begin(), erBufL_.end(), 0.0f);
    std::fill (erBufR_.begin(), erBufR_.end(), 0.0f);

    // Gate starts CLOSED (pre-onset silence) — reset across preset swap / unfreeze.
    gateState_        = GateState::Idle;
    envFollow_        = 0.0f;
    gateGain_         = 0.0f;
    holdCounter_      = 0;
    inputActiveSamps_ = 0;
    onsetAgeSamps_    = 0;
}

// Build the rising-gain early-reflection tap sets. Deterministic (fixed seed)
// so every render is bit-identical — the optimizer/gates need reproducibility.
void ReverseRoomEngine::rebuildTaps()
{
    const float sr       = static_cast<float> (sampleRate_);
    const int   rampSamp = std::max (8, static_cast<int> (rampMs_ * 0.001f * sr * sizeScale_));   // rise duration
    const int   minTap   = std::max (1, static_cast<int> (0.002f * sr));   // 2 ms floor
    // density 0 -> 16 taps (sparse "Concrete Stairs"), 1 -> kMaxTaps (dense).
    const int   n        = std::clamp (16 + static_cast<int> (density_ * (kMaxTaps - 16)),
                                       16, kMaxTaps);
    numTaps_ = n;

    for (int ch = 0; ch < 2; ++ch)
    {
        ERChannel& e = (ch == 0) ? erL_ : erR_;
        // Independent L/R pseudo-random sequences for wide stereo decorrelation.
        std::uint32_t s = (ch == 0) ? 0x1234567u : 0x89ABCDEu;
        auto rnd = [&s]() { s = s * 1664525u + 1013904223u; return (s >> 8) * (1.0f / 16777216.0f); };

        for (int k = 0; k < n; ++k)
        {
            // FULLY RANDOM tap positions (2026-07-04). The previous
            // roughly-even spacing (+-half-slot jitter) left the tap train
            // periodic: ramp/nTaps ~ 2.8-4.2 ms -> a comb resonance the boing
            // gate read as a massive ringing mode (213 Hz at ramp 470,
            // 289 Hz at ramp 310, up to +27 dB over the anchor). Uniform
            // random draws have no period -> no comb; density is preserved
            // (same tap count over the same ramp).
            const float pf = std::clamp (rnd(), 0.0f, 1.0f);
            int p = minTap + static_cast<int> (pf * static_cast<float> (rampSamp - minTap));
            p = std::clamp (p, 1, e.mask);
            e.pos[k] = p;

            // RISING gain from a floor: g = floor + (1-floor)*(t/ramp)^slope.
            // The floor keeps the onset off digital silence (which made an
            // infinite env_p2p cliff); the rising ramp IS the "reverse" swell.
            // (A bimodal dip-then-bump was tried to chase the reference's
            // env_p2p +24.6 secondary swell, but it broke env_shape_l1 for <1dB
            // of env_p2p — the reference's value comes from its mod+tap-comb
            // interaction, not a clean ER bloom. Kept the clean rising ramp:
            // the +60->+15 cliff fix is the win; +15 vs +24.6 is a smooth tail.)
            const float rel = std::clamp (static_cast<float> (p) / static_cast<float> (rampSamp), 0.0f, 1.0f);
            e.gain[k] = floorGain_ + (1.0f - floorGain_) * std::pow (rel, slope_);
        }

        // Bound the summed output level (sqrt(n) for incoherent taps).
        const float norm = 1.0f / std::sqrt (static_cast<float> (n));
        for (int k = 0; k < n; ++k)
            e.gain[k] *= norm;
    }
}

void ReverseRoomEngine::process (const float* inL, const float* inR,
                                 float* outL, float* outR, int numSamples)
{
    if (! prepared_)
    {
        std::memset (outL, 0, sizeof (float) * static_cast<size_t> (numSamples));
        std::memset (outR, 0, sizeof (float) * static_cast<size_t> (numSamples));
        return;
    }

    if (numSamples > maxBlock_)
    {
        // Host exceeded prepare()'s maxBlockSize. Process in maxBlock_-sized chunks
        // (sequential → gate / velvet / ER state stays continuous) rather than
        // truncating to maxBlock_ and dropping the rest of the host block.
        int off = 0;
        while (off < numSamples)
        {
            const int n = std::min (maxBlock_, numSamples - off);
            process (inL + off, inR + off, outL + off, outR + off, n);
            off += n;
        }
        return;
    }

    // ── 1) Rising-ER FIR: shape dry input into a swelling early-reflection
    //        burst (the "reverse" onset). Per channel, allocation-free. ──
    for (int ch = 0; ch < 2; ++ch)
    {
        ERChannel&   e   = (ch == 0) ? erL_ : erR_;
        const float* in  = (ch == 0) ? inL : inR;
        float*       out = (ch == 0) ? erBufL_.data() : erBufR_.data();
        const int    mask = e.mask;
        const int    nt   = numTaps_;
        float*       ring = e.ring.data();
        int          wp   = e.writePos;

        for (int i = 0; i < numSamples; ++i)
        {
            ring[wp] = in[i];
            float acc = 0.0f;
            for (int k = 0; k < nt; ++k)
                acc += e.gain[k] * ring[(wp - e.pos[k]) & mask];
            out[i] = acc;
            wp = (wp + 1) & mask;
        }
        e.writePos = wp;
    }

    // ── 2) Velvet-noise FIR tail (feed-forward) fed the swelling ER output, so
    //        the tail inherits the swell. Per-band exp-decay envelopes set the
    //        per-band T60 with NO recirculation → no FDN mid-decay floor. ──
    velvet_.process (erBufL_.data(), erBufR_.data(), outL, outR, numSamples);

    // ── 3) Input-keyed hard gate (the GATED-reverse signature). Keyed off the
    //        DRY input (inL/inR), applied as ONE smoothed scalar to both output
    //        channels: produces the pre-onset silence, the hold-while-input-present
    //        plateau, and the post-peak hard cliff to ~-90 dBFS that collapses the
    //        FDN tail (t60 5.1s -> ~0.06s). `g` is always SLEWED (never assigned)
    //        so both edges are continuous-valued -> no click. Deterministic
    //        post-multiply -> bit-null for the fleet (algo 9 = this 1 preset). ──
    const float atk    = envAtkCoeff_;
    const float rel    = envRelCoeff_;
    const float thr    = threshLin_;
    const float floorL = gateFloorLin_;
    const float openC  = gateOpenCoeff_;
    const float closeC = gateCloseCoeff_;

    float     env     = envFollow_;
    float     g       = gateGain_;
    GateState st      = gateState_;
    int       hc      = holdCounter_;
    int       iActive = inputActiveSamps_;
    int       age     = onsetAgeSamps_;
    const int winSamp = onsetWindowSamps_;

    for (int i = 0; i < numSamples; ++i)
    {
        // Dry-input peak-envelope follower (fast attack / slow release).
        const float x = std::fabs (inL[i]) + std::fabs (inR[i]);
        env += ((x > env) ? atk : rel) * (x - env);
        const bool present = (env > thr);

        if (present && iActive < holdMaxSamps_ * 16) ++iActive;   // burst-duration accumulator (capped)
        // Duration-dependent hold: base + holdPerSec per second of input presence,
        // capped. Impulse → ≈base (fast tail); sustained → ceiling (bands ring).
        const int effHold = std::min (holdMaxSamps_,
                                      holdSamples_ + static_cast<int> (holdPerSec_ * 0.001f * iActive));

        // Retriggerable hold state machine.
        switch (st)
        {
            case GateState::Idle:    if (present) { st = GateState::Open; iActive = 1; age = 0; } break;
            case GateState::Open:    if (! present) { st = GateState::Hold; hc = effHold; } break;
            case GateState::Hold:    if (present) st = GateState::Open;            // retrigger
                                     else if (--hc <= 0) st = GateState::Closing; break;
            case GateState::Closing: if (present) { st = GateState::Open; iActive = 1; age = 0; } break;  // retrigger
        }

        // Onset-keyed window close (ENDED bursts only): once the burst is older
        // than the window AND the input has stopped, cut immediately instead of
        // serving out the remaining hold — the REF reverse window is fixed-length
        // from onset. While input is still present the legacy hold semantics
        // stand untouched (a latch here killed the sustained stimuli: the piano
        // never drops below threshold, so the gate stayed shut for 22 s).
        if (winSamp > 0 && st != GateState::Idle)
        {
            if (age <= winSamp) ++age;   // capped: Closing never returns to Idle, so an
                                         // un-capped counter would overflow on long silence
            // SHORT bursts only (input itself ended inside the window): a long
            // sustained drive gets the legacy release — the anchor rings its
            // full per-band T60 after sustained input (the sustained-release
            // Schroeder fits need that tail), it only hard-windows one-shots.
            if (age > winSamp && ! present && iActive <= winSamp && st != GateState::Closing)
                st = GateState::Closing;
        }

        const float target = (st == GateState::Open || st == GateState::Hold) ? 1.0f : floorL;
        g += ((target > g) ? openC : closeC) * (target - g);   // always slewed → continuous

        outL[i] *= g;
        outR[i] *= g;
    }

    envFollow_        = env;
    gateGain_         = g;
    gateState_        = st;
    holdCounter_      = hc;
    inputActiveSamps_ = iActive;
    onsetAgeSamps_    = age;
}

// ── Universal setters ──────────────────────────────────────────────────────
// The velvet tail has no broadband tone/mod/saturation/loop, and the per-band
// tail tone is the engine's baked "Reverse" signature (tuned via the velvet
// defaults + DUSKVERB_VELVET). So the tone/mod setters are NO-OPS — the single
// algo-9 preset never disturbs the calibrated tail through them. Decay maps to a
// global tail-length scale so the Decay knob still does something musical.
void ReverseRoomEngine::setDecayTime (float seconds)   { velvet_.setGlobalDecayScale (std::max (0.05f, seconds) / 0.21f); }
void ReverseRoomEngine::setBassMultiply (float)        {}
void ReverseRoomEngine::setMidMultiply (float)         {}
void ReverseRoomEngine::setTrebleMultiply (float)      {}
void ReverseRoomEngine::setCrossoverFreq (float)       {}
void ReverseRoomEngine::setHighCrossoverFreq (float)   {}
void ReverseRoomEngine::setSaturation (float)          {}
void ReverseRoomEngine::setModDepth (float)            {}
void ReverseRoomEngine::setModRate (float)             {}
void ReverseRoomEngine::setTailSpinDepth (float)       {}
void ReverseRoomEngine::setTailSpinRate (float)        {}
void ReverseRoomEngine::setFreeze (bool)               {}

void ReverseRoomEngine::setSize (float size)
{
    velvet_.setSizeScale (0.6f + 1.0f * std::clamp (size, 0.0f, 1.0f));
    // 0..1 size -> 0.6..1.6x ER onset span (longer onset on bigger rooms).
    const float newScale = 0.6f + 1.0f * std::clamp (size, 0.0f, 1.0f);
    if (std::abs (newScale - sizeScale_) > 1.0e-4f)
    {
        sizeScale_ = newScale;
        if (prepared_) rebuildTaps();
    }
}

void ReverseRoomEngine::setTankDiffusion (float amount)
{
    const float a = std::clamp (amount, 0.0f, 1.0f);
    if (std::abs (a - density_) > 1.0e-4f)
    {
        density_ = a;
        if (prepared_) rebuildTaps();
    }
}
// ---- plugins/DuskVerb/src/dsp/ShimmerEngine.cpp


// ============================================================================
// ShimmerEngine v8 — classic Eno/Lanois rig topology.
// See header for full architecture description.
// ============================================================================

namespace
{
    constexpr float kTwoPi_ShimmerEngine = 6.283185307179586f;
}

// ============================================================================
// GranularPitchShifter (kept verbatim from v6 — this is the part that worked)
// ============================================================================

void ShimmerEngine::GranularPitchShifter::prepare (double sampleRate)
{
    sampleRate_ = sampleRate;
    // Buffer = 8 × grain size for plenty of lookback headroom across the
    // 1.0–4.0 pitch-ratio range.
    const int bufSize = DspUtils::nextPowerOf2 (8 * kGrainSize);
    buffer_.assign (static_cast<size_t> (bufSize), 0.0f);
    mask_ = bufSize - 1;
    clear();
    updateAntiAliasCutoff();
}

void ShimmerEngine::GranularPitchShifter::BiquadLP::setCoeffs (double sampleRate, float fc, float Q)
{
    const float omega = kTwoPi_ShimmerEngine * fc / static_cast<float> (sampleRate);
    const float cosw  = std::cos (omega);
    const float sinw  = std::sin (omega);
    const float alpha = sinw / (2.0f * Q);

    const float a0 = 1.0f + alpha;
    b0 = (1.0f - cosw) * 0.5f / a0;
    b1 = (1.0f - cosw) / a0;
    b2 = (1.0f - cosw) * 0.5f / a0;
    a1 = -2.0f * cosw / a0;
    a2 = (1.0f - alpha) / a0;
}

void ShimmerEngine::GranularPitchShifter::updateAntiAliasCutoff()
{
    // Cutoff = min(SR/2 × 0.9, SR/2 / pitchRatio_) so we never sample
    // content that would alias when the read pointer advances by ratio
    // samples per output sample. Two cascaded Butterworth biquads = 4-pole
    // / 24 dB-per-octave roll-off, > 30 dB rejection above the cutoff.
    const float nyquist = 0.5f * static_cast<float> (sampleRate_);
    const float fc      = std::min (nyquist * 0.9f,
                                    nyquist / std::max (pitchRatio_, 1.0f));
    aaStage1_.setCoeffs (sampleRate_, fc, kButterworthQ1);
    aaStage2_.setCoeffs (sampleRate_, fc, kButterworthQ2);
}

void ShimmerEngine::GranularPitchShifter::clear()
{
    std::fill (buffer_.begin(), buffer_.end(), 0.0f);
    writePos_ = 0;
    phase1_   = 0;
    phase2_   = kGrainSize / 2;
    readPos1_ = 0.0f;
    readPos2_ = static_cast<float> (kGrainSize) * 0.5f;
    aaStage1_.clear();
    aaStage2_.clear();
}

void ShimmerEngine::GranularPitchShifter::setPitchRatio (float ratio)
{
    pitchRatio_ = std::clamp (ratio, 0.5f, 4.0f);
    updateAntiAliasCutoff();
}

void ShimmerEngine::GranularPitchShifter::setModulation (float rateHz, float depth,
                                                          std::uint32_t seed)
{
    ratioMod_.prepare (static_cast<float> (sampleRate_), seed);
    ratioMod_.setRate (rateHz);
    ratioMod_.setDepth (1.0f);
    ratioModDepth_ = depth;
    ratioModEnabled_ = (depth > 0.0f);
}

void ShimmerEngine::GranularPitchShifter::startNewGrain (int& phase, float& readPos)
{
    phase = 0;
    const float lookback = std::ceil ((pitchRatio_ - 1.0f) * static_cast<float> (kGrainSize)) + 64.0f;
    readPos = static_cast<float> (writePos_) - lookback;
}

float ShimmerEngine::GranularPitchShifter::readLinear (float pos) const
{
    const int   intPos  = static_cast<int> (std::floor (pos));
    const float frac    = pos - static_cast<float> (intPos);
    const int   idx0    = intPos & mask_;
    const int   idx1    = (intPos + 1) & mask_;
    return buffer_[static_cast<size_t> (idx0)] * (1.0f - frac)
         + buffer_[static_cast<size_t> (idx1)] *         frac;
}

float ShimmerEngine::GranularPitchShifter::process (float input)
{
    // Bypass when pitchRatio is essentially unity. Saves ~5 % CPU per
    // sample AND avoids a known startup glitch: the dual-grain Hann
    // overlap takes ~kGrainSize/2 samples (~43 ms at 48 k) to ramp up
    // because grain 2 starts mid-window over zero-initialised buffer.
    // For Shimmer's PITCH=0 setting we want the engine to behave as a
    // plain reverb (input passes through to the reverb stage), not have
    // the snare's onset attenuated by 30 dB through Hann ramp-up.
    if (std::abs (pitchRatio_ - 1.0f) < 0.005f)
    {
        // Still keep the buffer + write-head alive so we can resume
        // gracefully if pitchRatio changes mid-block (parameter automation).
        const float filteredPassthrough = aaStage2_.process (aaStage1_.process (input));
        buffer_[static_cast<size_t> (writePos_)] = filteredPassthrough + DspUtils::kDenormalPrevention;
        writePos_ = (writePos_ + 1) & mask_;
        return filteredPassthrough;
    }

    // Anti-alias the input before it hits the grain buffer.
    const float filtered = aaStage2_.process (aaStage1_.process (input));

    // Write filtered input to buffer.
    buffer_[static_cast<size_t> (writePos_)] = filtered + DspUtils::kDenormalPrevention;

    // Read both grains with linear interpolation.
    const float v1 = readLinear (readPos1_);
    const float v2 = readLinear (readPos2_);

    // Hann window per grain.
    const float t1 = static_cast<float> (phase1_) / static_cast<float> (kGrainSize);
    const float t2 = static_cast<float> (phase2_) / static_cast<float> (kGrainSize);
    const float w1 = 0.5f * (1.0f - std::cos (kTwoPi_ShimmerEngine * t1));
    const float w2 = 0.5f * (1.0f - std::cos (kTwoPi_ShimmerEngine * t2));

    const float out = v1 * w1 + v2 * w2;

    // Slow random-walk modulation of the per-sample read advance. At ±0.5%
    // ratio variation (≈ ±8 cents) the pitch sounds steady, but each cascade
    // cycle pitches by a slightly different amount — so the cumulative
    // cascade doesn't stack on exact harmonic frequencies, which is what
    // creates the sharp metallic peaks at e.g. 376/428/758/1314 Hz when a
    // 200 Hz fundamental migrates octave-by-octave through the loop.
    // Modulation smears those peaks across narrow bands so they blend with
    // the rest of the cascade tail (the "subdued" character the user
    // observed in external reference Shimmer).
    const float effectiveRatio = ratioModEnabled_
        ? pitchRatio_ * (1.0f + ratioModDepth_ * ratioMod_.next())
        : pitchRatio_;

    // Advance grain phases; reset when a grain reaches kGrainSize.
    readPos1_ += effectiveRatio;
    readPos2_ += effectiveRatio;
    ++phase1_;
    ++phase2_;
    if (phase1_ >= kGrainSize) startNewGrain (phase1_, readPos1_);
    if (phase2_ >= kGrainSize) startNewGrain (phase2_, readPos2_);

    writePos_ = (writePos_ + 1) & mask_;
    return out;
}

// ============================================================================
// ShimmerEngine
// ============================================================================

void ShimmerEngine::prepare (double sampleRate, int maxBlockSize)
{
    sampleRate_ = sampleRate;
    maxBlockSize_ = maxBlockSize;

    pitchL_.prepare (sampleRate);
    pitchR_.prepare (sampleRate);

    // Defocus the cascade peaks via random-walk pitch-ratio modulation.
    // For peak smearing to work, the modulation must change appreciably
    // between consecutive cascade cycles (~50 ms apart). At rates of
    // 5-7 Hz the LFO traverses ~25-35% of its excursion in one cascade
    // period, so consecutive cycles see distinctly different ratios.
    // ±1.5% (~26 cents) depth is enough to noticeably smear the sharp
    // resonant peaks of the migrated harmonics; lower depth leaves the
    // peaks visible. Slight chorus-like wobble is the audible side
    // effect — period-correct for analog shimmer rigs which had wow/
    // flutter from tape and tube modulators in the loop.
    pitchL_.setModulation (5.7f, 0.015f, 0xC0FFEEu);
    pitchR_.setModulation (7.3f, 0.015f, 0xBADC0DEu);
    pitch2L_.prepare (sampleRate);
    pitch2R_.prepare (sampleRate);
    pitch2L_.setModulation (4.9f, 0.020f, 0x5EED01u);
    pitch2R_.setModulation (6.7f, 0.020f, 0x5EED02u);
    pitchDownL_.prepare (sampleRate);
    pitchDownR_.prepare (sampleRate);
    pitchDownL_.setModulation (5.3f, 0.018f, 0xD0117Au);
    pitchDownR_.setModulation (6.1f, 0.018f, 0xD0117Bu);
    pitchDownL_.setPitchRatio (kVoiceDownRatio);   // −1 oct (×0.5 → 500 Hz)
    pitchDownR_.setPitchRatio (kVoiceDownRatio);
    pitchSubL_.prepare (sampleRate);
    pitchSubR_.prepare (sampleRate);
    pitchSubL_.setModulation (4.7f, 0.018f, 0x5B0117Au);
    pitchSubR_.setModulation (5.9f, 0.018f, 0x5B0117Bu);
    pitchSubL_.setPitchRatio (kVoiceSubRatio);     // −2 oct (×0.25 → 250 Hz)
    pitchSubR_.setPitchRatio (kVoiceSubRatio);
    // Dry-fed octave cascade: 4 mono −12 st stages, each modulated at its own rate/seed so the
    // octave reads as a smooth band (not a discrete mode). Feed-forward from the dry input.
    for (int i = 0; i < kNumOctaves; ++i)
    {
        octGenL_[i].prepare (sampleRate);
        octGenL_[i].setPitchRatio (0.5f);          // −1 oct per stage (cascade: 500/250/125/62)
        octGenL_[i].setModulation (4.3f + 0.6f * static_cast<float> (i), 0.020f,
                                   0x0C7A5E01u + static_cast<std::uint32_t> (i));
    }
    stereoMod_.prepare (sampleRate);
    air_.prepare (sampleRate);
    air_.setMix (airMix_);
    stereoMod_.setParams (stereoModRate_, stereoModDepth_, sampleRate);
    tailSpin_.prepare (sampleRate);
    tailNoise_.prepare (sampleRate);
    noiseDuckKey_.prepare (sampleRate);
    noiseDuckSlew_ = 1.0f - std::exp (-1.0f / (0.050f * static_cast<float> (sampleRate)));
    noiseDuckG_ = 1.0f;
    tailNoise_.setGain (noiseGain_);

    // Hall reverb baseline: long, lush, slightly dark (period-correct
    // for the late-1970s digital hall hardware character that the original Eno/Lanois rig used).
    reverb_.prepare (sampleRate, maxBlockSize);
    reverb_.setDecayTime         (4.0f);
    reverb_.setSize              (0.75f);
    reverb_.setBassMultiply      (1.10f);
    reverb_.setMidMultiply       (1.00f);
    reverb_.setTrebleMultiply    (0.85f);
    reverb_.setCrossoverFreq     (550.0f);
    reverb_.setHighCrossoverFreq (3500.0f);
    reverb_.setSaturation        (0.0f);
    reverb_.setTankDiffusion     (0.85f);

    // Dense-diffusion tank, same voicing baseline as the FDN above. DenseHall
    // has no tank-diffusion or saturation knob (diffusion is structural, and
    // the shimmer's softClip saturation lives in the feedback loop, not here).
    denseReverb_.prepare (sampleRate, maxBlockSize);
    denseReverb_.setDecayTime         (4.0f);
    denseReverb_.setSize              (0.75f);
    denseReverb_.setBassMultiply      (1.10f);
    denseReverb_.setMidMultiply       (1.00f);
    denseReverb_.setTrebleMultiply    (0.85f);
    denseReverb_.setCrossoverFreq     (550.0f);
    denseReverb_.setHighCrossoverFreq (3500.0f);

    reverbInL_.assign (static_cast<size_t> (maxBlockSize), 0.0f);
    reverbInR_.assign (static_cast<size_t> (maxBlockSize), 0.0f);
    wetL_.assign      (static_cast<size_t> (maxBlockSize), 0.0f);
    wetR_.assign      (static_cast<size_t> (maxBlockSize), 0.0f);

    // Feedback delay line — fixed 50 ms acoustic delay, decoupled from
    // block size. Buffer must be ≥ maxBlockSize so that a single block's
    // reads + writes never lap the pointer (which would corrupt the delay
    // by overwriting a slot before the next block has read it).
    const int requestedDelay = static_cast<int> (sampleRate * 0.050);
    fbDelaySamples_   = std::max (requestedDelay, maxBlockSize + 1);
    fbDelayWritePos_  = 0;
    fbDelayLineL_.assign (static_cast<size_t> (fbDelaySamples_), 0.0f);
    fbDelayLineR_.assign (static_cast<size_t> (fbDelaySamples_), 0.0f);

    const float sr = static_cast<float> (sampleRate);
    fbHpfL_.setHPCutoff (feedbackHpfHz_, sr);
    fbHpfR_.setHPCutoff (feedbackHpfHz_, sr);
    fbLpfL_.setLPCutoff (kFeedbackLpfHz, sr);
    fbLpfR_.setLPCutoff (kFeedbackLpfHz, sr);
    fbHpfL_.clear(); fbHpfR_.clear();
    fbLpfL_.clear(); fbLpfR_.clear();
    hfShelfL_.setHPCutoff (hfSustainHz_, sr);
    hfShelfR_.setHPCutoff (hfSustainHz_, sr);
    hfShelfL_.clear(); hfShelfR_.clear();

    // Loop-hi limiter: re-derive every SR-dependent coeff from the stored config
    // so a sample-rate change keeps the ratio-keyed air duck in sync (same
    // re-apply-in-prepare pattern as the hfShelf + noiseDuck paths above).
    // loopHiCfg_ retains the user params; only the SR-derived coeffs go stale.
    // On the normal render path setLoopHiLimiter runs after prepare and overwrites
    // these, so this is inert (bit-null) there; it only bites on a bare SR change.
    loopHiCfg_.updateCoeffs (sampleRate_);
    loopHiCutL_.design (loopHiCfg_.loHz, loopHiCfg_.hiHz, loopHiCfg_.maxCutDb, sampleRate_);
    loopHiCutR_.design (loopHiCfg_.loHz, loopHiCfg_.hiHz, loopHiCfg_.maxCutDb, sampleRate_);
    const float srLoopHi = static_cast<float> (sampleRate_ > 1000.0 ? sampleRate_ : 48000.0);
    loopHiHpCoeff_ = 1.0f - std::exp (-kTwoPi_ShimmerEngine * loopHiCfg_.loHz / srLoopHi);
    loopHiEnvAtk_  = 1.0f - std::exp (-1.0f / (0.030f * srLoopHi));   // 30 ms envelope attack
    loopHiEnvRel_  = 1.0f - std::exp (-1.0f / (0.300f * srLoopHi));   // 300 ms release
    loopHiDet_.clear();
    loopHiWetEnv_ = loopHiInEnv_ = 0.0f;
    loopHiHpWetL_ = loopHiHpWetR_ = loopHiHpInL_ = loopHiHpInR_ = 0.0f;

    updatePitchRatio();
    prepared_ = true;
}

void ShimmerEngine::clearBuffers()
{
    pitchL_.clear();
    pitchR_.clear();
    pitch2L_.clear();
    pitch2R_.clear();
    pitchDownL_.clear();
    pitchDownR_.clear();
    pitchSubL_.clear();
    pitchSubR_.clear();
    for (int i = 0; i < kNumOctaves; ++i) octGenL_[i].clear();
    tailNoise_.clear();
    stereoMod_.clear();
    air_.clear();
    tailSpin_.clear();
    reverb_.clearBuffers();
    denseReverb_.clear();
    std::fill (reverbInL_.begin(), reverbInL_.end(), 0.0f);
    std::fill (reverbInR_.begin(), reverbInR_.end(), 0.0f);
    std::fill (wetL_.begin(),      wetL_.end(),      0.0f);
    std::fill (wetR_.begin(),      wetR_.end(),      0.0f);
    std::fill (fbDelayLineL_.begin(), fbDelayLineL_.end(), 0.0f);
    std::fill (fbDelayLineR_.begin(), fbDelayLineR_.end(), 0.0f);
    fbDelayWritePos_ = 0;
    fbHpfL_.clear(); fbHpfR_.clear();
    fbLpfL_.clear(); fbLpfR_.clear();
    hfShelfL_.clear(); hfShelfR_.clear();
    // Noise-duck + ratio-keyed loop-hi limiter state — reset so a stale reduction
    // (or a held-open duck) can't carry across a reset / preset swap.
    noiseDuckKey_.clear();
    noiseDuckG_ = 1.0f;
    loopHiDet_.clear();
    loopHiWetEnv_ = loopHiInEnv_ = 0.0f;
    loopHiHpWetL_ = loopHiHpWetR_ = loopHiHpInL_ = loopHiHpInR_ = 0.0f;
    loopHiCutL_.clear(); loopHiCutR_.clear();
}

// ============================================================================
// Setters
// ============================================================================

void ShimmerEngine::setDecayTime (float seconds)
{
    // Pass through to BOTH tanks. Each has its own internal range clamping.
    // Long decays (3-6 s) are typical for shimmer cascade.
    reverb_.setDecayTime (seconds);
    denseReverb_.setDecayTime (seconds);
}

void ShimmerEngine::setSize         (float size) { reverb_.setSize (size); denseReverb_.setSize (size); }
void ShimmerEngine::setBassMultiply (float mult) { reverb_.setBassMultiply (mult); denseReverb_.setBassMultiply (mult); }
void ShimmerEngine::setMidMultiply  (float mult) { reverb_.setMidMultiply  (mult); denseReverb_.setMidMultiply  (mult); }
void ShimmerEngine::setTrebleMultiply (float mult) { reverb_.setTrebleMultiply (mult); denseReverb_.setTrebleMultiply (mult); }
void ShimmerEngine::setCrossoverFreq  (float hz)   { reverb_.setCrossoverFreq  (hz); denseReverb_.setCrossoverFreq (hz); }
void ShimmerEngine::setHighCrossoverFreq (float hz){ reverb_.setHighCrossoverFreq (hz); denseReverb_.setHighCrossoverFreq (hz); }
void ShimmerEngine::setTankDiffusion (float amount){ reverb_.setTankDiffusion (amount); }  // FDN only; DenseHall diffusion is structural
void ShimmerEngine::setDownOctaveMix (float mix)   { downMix_ = std::clamp (mix, 0.0f, 4.0f); }
void ShimmerEngine::setSubOctaveMix  (float mix)   { subMix_  = std::clamp (mix, 0.0f, 4.0f); }
void ShimmerEngine::setHFAir (float mix) { airMix_ = mix; air_.setMix (mix); }
void ShimmerEngine::setStereoMod (float rateHz, float depth)
{
    stereoModRate_  = rateHz;
    stereoModDepth_ = depth;
    stereoMod_.setParams (rateHz, depth, sampleRate_);
}
void ShimmerEngine::setFeedbackHpfHz (float hz)
{
    feedbackHpfHz_ = std::clamp (hz, 15.0f, 200.0f);
    const float sr = static_cast<float> (sampleRate_);
    fbHpfL_.setHPCutoff (feedbackHpfHz_, sr);
    fbHpfR_.setHPCutoff (feedbackHpfHz_, sr);
}

void ShimmerEngine::setSaturation (float amount)
{
    saturationAmount_ = std::clamp (amount, 0.0f, 1.0f);
}

void ShimmerEngine::setOutputHeadroom (float h)
{
    // Clamp to [1, 8]: below 1 would tighten the clip (pointless / more grit),
    // above 8 makes the output effectively linear (no safety limit at all).
    outputHeadroom_ = std::clamp (h, 1.0f, 8.0f);
}

// DEPTH (mod_depth, 0..1) → PITCH semitones (0..24). 0 = unity (no shift),
// 0.5 = +12 (octave up — canonical Eno Choir), 1.0 = +24 (Cascading Heaven).
void ShimmerEngine::setModDepth (float depth)
{
    const float clamped = std::clamp (depth, 0.0f, 1.0f);
    pitchSemitones_ = clamped * 24.0f;
    if (prepared_) updatePitchRatio();
}

// RATE (mod_rate, 0.1..10 Hz) → FEEDBACK gain (0..kFeedbackMax). Maps the
// Hz value linearly so the user gets useful resolution across the cascade-
// strength range. Hard-capped at kFeedbackMax (0.95) for stability.
void ShimmerEngine::setModRate (float hz)
{
    const float clamped = std::clamp (hz, 0.1f, 10.0f);
    const float fb01 = (clamped - 0.1f) / 9.9f;        // 0..1
    feedbackGain_ = std::clamp (fb01 * kFeedbackMax, 0.0f, kFeedbackMax);
}

void ShimmerEngine::setFreeze (bool frozen)
{
    frozen_ = frozen;
    reverb_.setFreeze (frozen);
    denseReverb_.setFreeze (frozen);
}

void ShimmerEngine::setModeSmear (float depthSamples, float rateHz)
{
    reverb_.setModeSmear (depthSamples, rateHz);   // Black Hole + Deep Blue Day use the FDN reverb_
}
void ShimmerEngine::setSustainLimiterMid (float lo, float hi, float thr, float cut,
                                          float atk, float relF, float relS)
{
    // In-loop sustained-energy limiter in the internal reverb tank(s); the shimmer's
    // OWN pitch feedback loop is untouched (its air-band runaway needs a ratio-keyed
    // detector — a separate, later feature). maxCutDb 0 = bit-null.
    reverb_.setSustainLimiterMid      (lo, hi, thr, cut, atk, relF, relS);
    denseReverb_.setSustainLimiterMid (lo, hi, thr, cut, atk, relF, relS);
}
void ShimmerEngine::setSustainLimiterLow (float lo, float hi, float thr, float cut,
                                          float atk, float relF, float relS)
{
    reverb_.setSustainLimiterLow      (lo, hi, thr, cut, atk, relF, relS);
    denseReverb_.setSustainLimiterLow (lo, hi, thr, cut, atk, relF, relS);
}
void ShimmerEngine::setLoopHiLimiter (float loHz, float hiHz, float ratioThrDb, float maxCutDb,
                                      float atkMs, float relFastMs, float relSlowMs)
{
    loopHiCfg_.set (loHz, hiHz, ratioThrDb, maxCutDb, atkMs, relFastMs, relSlowMs, sampleRate_);
    loopHiCutL_.design (loopHiCfg_.loHz, loopHiCfg_.hiHz, loopHiCfg_.maxCutDb, sampleRate_);
    loopHiCutR_.design (loopHiCfg_.loHz, loopHiCfg_.hiHz, loopHiCfg_.maxCutDb, sampleRate_);
    const float sr = static_cast<float> (sampleRate_ > 1000.0 ? sampleRate_ : 48000.0);
    loopHiHpCoeff_ = 1.0f - std::exp (-kTwoPi_ShimmerEngine * loopHiCfg_.loHz / sr);
    loopHiEnvAtk_  = 1.0f - std::exp (-1.0f / (0.030f * sr));   // 30 ms envelope attack
    loopHiEnvRel_  = 1.0f - std::exp (-1.0f / (0.300f * sr));   // 300 ms release
    loopHiDet_.clear();
    loopHiWetEnv_ = loopHiInEnv_ = 0.0f;
    loopHiHpWetL_ = loopHiHpWetR_ = loopHiHpInL_ = loopHiHpInR_ = 0.0f;
}

void ShimmerEngine::setUseDenseReverb (bool on) { useDenseReverb_ = on; }
void ShimmerEngine::setUseTailSpin    (bool on) { useTailSpin_ = on; }
void ShimmerEngine::setTailNoise      (float gain, float hpHz, float lpHz) { noiseGain_ = gain; tailNoise_.setGain (gain); tailNoise_.setBand (hpHz, lpHz); }
void ShimmerEngine::setNoiseSustainDuck (float amt)
{
    noiseDuckAmt_ = std::clamp (amt, 0.0f, 1.0f);
    noiseDuckG_ = 1.0f;
}
void ShimmerEngine::setUpVoiceScale (float v1, float v2)
{
    voice1Scale_ = std::clamp (v1, 0.0f, 4.0f);
    voice2Scale_ = std::clamp (v2, 0.0f, 4.0f);
}
void ShimmerEngine::setOctaveCascade (const float gains[4])
{
    bool any = false;
    for (int i = 0; i < kNumOctaves; ++i)
    {
        octGain_[i] = std::clamp (gains[i], 0.0f, 8.0f);
        any = any || (octGain_[i] > 1.0e-6f);
    }
    octActive_ = any;
}

void ShimmerEngine::setHFSustainDb (float db, float cornerHz)
{
    // Clamp to +12 dB: the shelf compounds per loop pass, and the loop's
    // softClip + kFeedbackLoopAttn bound it, but past ~12 dB the boosted
    // band pins the clip every pass (distorted ring, not longer T60).
    db = std::clamp (db, 0.0f, 12.0f);
    hfSustainGain_ = (db > 0.01f) ? std::pow (10.0f, db / 20.0f) - 1.0f : 0.0f;
    hfSustainHz_   = std::clamp (cornerHz, 1000.0f, 12000.0f);
    if (prepared_)
    {
        const float sr = static_cast<float> (sampleRate_);
        hfShelfL_.setHPCutoff (hfSustainHz_, sr);
        hfShelfR_.setHPCutoff (hfSustainHz_, sr);
    }
}

void ShimmerEngine::updatePitchRatio()
{
    // Convert semitones to ratio. ratio = 2^(semitones / 12).
    const float ratio = std::pow (2.0f, pitchSemitones_ / 12.0f);
    pitchL_.setPitchRatio (ratio);
    pitchR_.setPitchRatio (ratio);
    pitch2L_.setPitchRatio (ratio * kVoice2OctaveMul);   // octave above -> fills the top band
    pitch2R_.setPitchRatio (ratio * kVoice2OctaveMul);
}

// ============================================================================
// process — v9 topology: dry input → reverb (forward path);
//                        wet → delay → pitchShift → softClip×fb → mix node.
// ============================================================================

void ShimmerEngine::process (const float* inL, const float* inR,
                             float* outL, float* outR, int numSamples)
{
    if (! prepared_)
    {
        std::memset (outL, 0, sizeof (float) * static_cast<size_t> (numSamples));
        std::memset (outR, 0, sizeof (float) * static_cast<size_t> (numSamples));
        return;
    }

    if (numSamples > maxBlockSize_)
        numSamples = maxBlockSize_;

    const float satThreshold = 1.0f - saturationAmount_ * 0.6f;
    const float satCeiling   = 2.0f;
    const float fb           = feedbackGain_;

    // ── Pass 1: build reverb input = drive(input) + softClipped(pitched fb).
    // The pitch shifter NO LONGER processes the dry input — only the delayed
    // wet feedback. That preserves the natural reverb tail for the dry
    // signal (first-pass through reverb is unpitched) and adds the shimmer
    // cascade purely via the feedback loop.
    //
    // Pass 1 walks a local read cursor through the 50 ms circular delay
    // line; Pass 3 walks the member write cursor through the same line.
    // Both start at fbDelayWritePos_ and advance per sample, so the wet
    // sample written at slot k in this block is the one read back at slot
    // k after the buffer wraps once (= fbDelaySamples_ samples later).
    int readPos = fbDelayWritePos_;
    for (int n = 0; n < numSamples; ++n)
    {
        // Drive softClip on input — the saturation knob still affects the
        // dry path entering the reverb.
        const float driveL = DspUtils::softClip (inL[n], satThreshold, satCeiling);
        const float driveR = DspUtils::softClip (inR[n], satThreshold, satCeiling);

        // Pitch-shift the delayed wet directly. At PITCH=0 the shifter
        // bypasses to a filtered passthrough, collapsing the engine to a
        // feedback-extended reverb.
        const float fbSrcL = fbDelayLineL_[static_cast<size_t> (readPos)];
        const float fbSrcR = fbDelayLineR_[static_cast<size_t> (readPos)];
        // Per-preset scale on the upward voices (voice1 +12 st fills 250-500, voice2 +24 st fills
        // 500-1k). Deep Blue Day boosts these to regenerate the mid tail harder on transients
        // (the snare body ×2/×4 → the 250 Hz-1 kHz body REF has). Default 1.0 → ×1.0f bypass
        // → bit-identical to legacy for Black Hole + every other preset.
        float pitchedFbL = kVoice1Mix * voice1Scale_ * pitchL_.process (fbSrcL)
                         + kVoice2Mix * voice2Scale_ * pitch2L_.process (fbSrcL);
        float pitchedFbR = kVoice1Mix * voice1Scale_ * pitchR_.process (fbSrcR)
                         + kVoice2Mix * voice2Scale_ * pitch2R_.process (fbSrcR);
        // Octave-DOWN voice IN THE FEEDBACK: pitch the feedback down −1 oct + add back.
        // The loop regenerates the descending ladder (500→250→125 Hz) GRADUALLY over
        // its 50 ms passes → loud deep low that builds SMOOTHLY (no abrupt "kick-in"
        // like a self-feeding output ladder). softClip bounds the per-grain peaks; the
        // 60 Hz HPF below caps the sub; a MODERATE downMix_ keeps the loop gain < 1 so
        // it stays bounded (the clip was over-cranking to 3.5). 0 → branch skipped (byte-
        // identical on non-shimmer presets; this loop is the recursive-feedback TU, see the .h).
        if (downMix_ > 0.0f)
        {
            pitchedFbL += downMix_ * DspUtils::softClip (pitchDownL_.process (fbSrcL),
                                                         kFeedbackSoftClipKnee, kFeedbackSoftClipCeil);
            pitchedFbR += downMix_ * DspUtils::softClip (pitchDownR_.process (fbSrcR),
                                                         kFeedbackSoftClipKnee, kFeedbackSoftClipCeil);
        }
        // Octave-DOWN-2 (sub) voice: reaches 250 Hz in ONE step where the −1 oct cascade
        // dies out, then the loop regenerates 125→62 Hz from it → the deep low wash REF
        // Shimmer has. Same softClip + loop band-pass keep it bounded. 0 → branch skipped
        // (byte-identical on non-shimmer presets; recursive-feedback TU, see the .h note).
        if (subMix_ > 0.0f)
        {
            pitchedFbL += subMix_ * DspUtils::softClip (pitchSubL_.process (fbSrcL),
                                                        kFeedbackSoftClipKnee, kFeedbackSoftClipCeil);
            pitchedFbR += subMix_ * DspUtils::softClip (pitchSubR_.process (fbSrcR),
                                                        kFeedbackSoftClipKnee, kFeedbackSoftClipCeil);
        }

        // Band-pass the pitch-shifted feedback: HPF removes grain-rate
        // sub-harmonics that would otherwise rumble up over time; LPF
        // tames the upper-spectrum metallic ring caused by repeated
        // pitch-up cycles concentrating energy near the AA-filter wall.
        float bandedL = fbLpfL_.processLP (fbHpfL_.processHP (pitchedFbL));
        float bandedR = fbLpfR_.processLP (fbHpfR_.processHP (pitchedFbR));

        // HF-sustain compensation shelf: the tank is HF-lossy per pass (that
        // loss, not the LPF above, caps HF T60). Re-enter the loop with the
        // >4 kHz band lifted so the HF ring survives more passes. First-order
        // high-shelf: x + g * HP(x). gain <= 0 → skipped (bit-null pattern,
        // same as the downMix_/subMix_ branches above; recursive-feedback TU).
        if (hfSustainGain_ > 0.0f)
        {
            bandedL += hfSustainGain_ * hfShelfL_.processHP (bandedL);
            bandedR += hfSustainGain_ * hfShelfR_.processHP (bandedR);
        }

        // RATIO-KEYED loop hi limiter (setLoopHiLimiter): duck the regenerating air
        // band when wet-hi grossly exceeds input-hi (piano: input has no air, the
        // pitch loop makes it; pink: input-hi large -> ratio small -> off). Inactive
        // -> skipped -> bit-null.
        if (loopHiCfg_.active)
        {
            // one-pole HP envelopes (wet = the banded fb; input = this sample's dry)
            loopHiHpWetL_ += loopHiHpCoeff_ * (bandedL - loopHiHpWetL_);
            loopHiHpWetR_ += loopHiHpCoeff_ * (bandedR - loopHiHpWetR_);
            const float wetHi = 0.5f * (std::abs (bandedL - loopHiHpWetL_)
                                      + std::abs (bandedR - loopHiHpWetR_));
            loopHiHpInL_ += loopHiHpCoeff_ * (inL[n] - loopHiHpInL_);
            loopHiHpInR_ += loopHiHpCoeff_ * (inR[n] - loopHiHpInR_);
            const float inHi = 0.5f * (std::abs (inL[n] - loopHiHpInL_)
                                     + std::abs (inR[n] - loopHiHpInR_));
            loopHiWetEnv_ += (wetHi > loopHiWetEnv_ ? loopHiEnvAtk_ : loopHiEnvRel_) * (wetHi - loopHiWetEnv_);
            loopHiInEnv_  += (inHi  > loopHiInEnv_  ? loopHiEnvAtk_ : loopHiEnvRel_) * (inHi  - loopHiInEnv_);
            const float ratio = loopHiWetEnv_ / std::max (loopHiInEnv_, 1.0e-4f);
            const bool present = loopHiInEnv_ > 1.0e-4f || loopHiWetEnv_ > 1.0e-4f;
            const float red = loopHiDet_.advanceUnit (ratio, loopHiCfg_, present);
            bandedL -= red * loopHiCutL_.band (bandedL);
            bandedR -= red * loopHiCutR_.band (bandedR);
        }

        // Apply user feedback gain × kFeedbackLoopAttn, then softClip
        // as a runaway safety net.
        const float fbL = DspUtils::softClip (bandedL * fb * kFeedbackLoopAttn,
                                              kFeedbackSoftClipKnee, kFeedbackSoftClipCeil);
        const float fbR = DspUtils::softClip (bandedR * fb * kFeedbackLoopAttn,
                                              kFeedbackSoftClipKnee, kFeedbackSoftClipCeil);

        // Dry-fed octave cascade (mono, feed-forward): each −12 st stage pitches the previous
        // stage's output down another octave, summed at its own gain → an independent, EVEN
        // 500/250/125/62 Hz descent (REF's structure) that does NOT depend on the feedback
        // loop. Fed from the raw dry (inL/inR), so a transient generates the full cascade in one
        // pass instead of starving the feedback voices. octActive_ false → skipped → bit-null.
        float octMono = 0.0f;
        if (octActive_)
        {
            // Feed SILENCE while frozen: the octave cascade reads the LIVE dry input (unlike the
            // pitch voices, which read the frozen feedback), so tracking live input during a freeze
            // would leak that freeze-time material into the octaves on un-freeze. Silence drains
            // the grain buffers so the held tank stays clean and the cascade resumes from the live
            // input on release. (When frozen the reverb discards its input anyway; this keeps the
            // generator state aligned with the freeze so there's no unfreeze transient.)
            float src = frozen_ ? 0.0f : 0.5f * (inL[n] + inR[n]);
            for (int i = 0; i < kNumOctaves; ++i)
            {
                src = octGenL_[i].process (src);        // cascade: 1k→500→250→125→62
                octMono += octGain_[i] * src;
            }
        }

        // Mix node: dry input + pitched feedback + dry-fed octaves → reverb input.
        reverbInL_[static_cast<size_t> (n)] = driveL + fbL + octMono;
        reverbInR_[static_cast<size_t> (n)] = driveR + fbR + octMono;

        if (++readPos >= fbDelaySamples_) readPos = 0;
    }

    // ── Pass 2: reverb on the (dry + pitched-fb) mix → wet. ──
    if (useDenseReverb_)
        denseReverb_.process (reverbInL_.data(), reverbInR_.data(),
                              wetL_.data(),      wetR_.data(),      numSamples);
    else
        reverb_.process (reverbInL_.data(), reverbInR_.data(),
                         wetL_.data(),      wetR_.data(),      numSamples);

    // ── Pass 3: emit wet (with output trim) AND write wet into the
    // feedback delay line for next-cycle pitch + recirculation. Engine
    // outputs WET ONLY; dry/wet mix happens in the DuskVerbEngine wrapper
    // via setMix.
    for (int n = 0; n < numSamples; ++n)
    {
        const float wL = wetL_[static_cast<size_t> (n)];
        const float wR = wetR_[static_cast<size_t> (n)];

        // wet (with up + down pitched feedback already folded in by the loop) →
        // delay line. The down octave regenerates through the SAME loop as the up
        // shimmer → both octaves build with identical timing (no late "kick-in").
        fbDelayLineL_[static_cast<size_t> (fbDelayWritePos_)] = wL;
        fbDelayLineR_[static_cast<size_t> (fbDelayWritePos_)] = wR;
        if (++fbDelayWritePos_ >= fbDelaySamples_) fbDelayWritePos_ = 0;

        float oL = wL, oR = wR;

        // Tail spin-comb on the OUTPUT ONLY (post-feedback-write → the recirculating
        // cascade stays un-spun). Smears the FDN's metallic HF; off → oL/oR untouched.
        if (useTailSpin_) tailSpin_.process (oL, oR);

        // Stereo modulation on the OUTPUT ONLY (post-feedback-write so the loop is
        // unaffected). depth 0 → struct inactive → oL/oR unchanged → bit-null.
        // Post-loop HF-air voice (genuine >12 kHz air; bypasses the reverb HF-damp + loop LPF).
        // Taps the raw wet (wL/wR), pitches its 6-12 kHz up to 12-24 k. mix 0 → bit-null.
        if (air_.active) air_.process (wL, wR, oL, oR);
        if (stereoMod_.active) stereoMod_.process (oL, oR);
        // Tail noise floor — envelope-tracked to the wet, fades with the decay (REF's
        // dense noise-like fade; masks the sparse-mode ring). gain 0 → skipped → bit-null.
        // NOISE SUSTAIN-DUCK (2026-07-08): the noise's gentle LP leaks 8-16 kHz; on a
        // 22 s sustained stem the envelope-tracked noise runs continuously → measured
        // +24 dB of Black Hole's piano-air +36.9. Duck the noise while INPUT sustains
        // (the piano-air window); it returns within ~250 ms of input-off, so the
        // release-measured benefits (T60-16k lift, cent_500, spec_L1) survive.
        // duckAmt 0 → the legacy call → bit-null.
        if (tailNoise_.active())
        {
            if (noiseDuckAmt_ > 0.0f)
            {
                const bool present = noiseDuckKey_.advance (std::abs (inL[n]) + std::abs (inR[n]));
                const float tgt = present ? (1.0f - noiseDuckAmt_) : 1.0f;
                noiseDuckG_ += noiseDuckSlew_ * (tgt - noiseDuckG_);
                float nl = 0.0f, nr = 0.0f;
                tailNoise_.process (wL, wR, nl, nr);
                oL += noiseDuckG_ * nl;
                oR += noiseDuckG_ * nr;
            }
            else
                tailNoise_.process (wL, wR, oL, oR);
        }
        // Output limiter. h==1 → plain tanh (bit-null). h>1 → h*tanh(x/h): the
        // knee moves to ±h so long-decay buildup (Deep Blue Day) stays linear
        // and doesn't emit odd-harmonic (3k/5k) grit on sustained tones.
        const float gL = oL * kWetOutputGain, gR = oR * kWetOutputGain;
        const float h = outputHeadroom_;
        outL[n] = (h == 1.0f) ? std::tanh (gL) : h * std::tanh (gL / h);
        outR[n] = (h == 1.0f) ? std::tanh (gR) : h * std::tanh (gR / h);
    }
}
// ---- plugins/DuskVerb/src/dsp/SixAPTankEngine.cpp


void SixAPTankEngine::DelayLine::allocate (int maxSamples)
{
    int size = DspUtils::nextPowerOf2 (std::max (maxSamples + 4, 16));
    buffer.assign (static_cast<size_t> (size), 0.0f);
    mask = size - 1;
    writePos = 0;
}

void SixAPTankEngine::DelayLine::clear()
{
    std::fill (buffer.begin(), buffer.end(), 0.0f);
    writePos = 0;
}

float SixAPTankEngine::DelayLine::readInterpolated (float delaySamples) const
{
    int   intPart  = static_cast<int> (delaySamples);
    float fracPart = delaySamples - static_cast<float> (intPart);
    int   readPos  = (writePos - intPart - 1) & mask;
    return DspUtils::cubicHermite (buffer.data(), mask, readPos, 1.0f - fracPart);
}

void SixAPTankEngine::Allpass::allocate (int maxSamples)
{
    int size = DspUtils::nextPowerOf2 (std::max (maxSamples + 4, 16));
    buffer.assign (static_cast<size_t> (size), 0.0f);
    mask = size - 1;
    writePos = 0;
}

void SixAPTankEngine::Allpass::clear()
{
    std::fill (buffer.begin(), buffer.end(), 0.0f);
    writePos = 0;
}

SixAPTankEngine::SixAPTankEngine()
{
    // Distinct seeds so the L/R LFOs trace independent random paths from the
    // first sample; identical seeds would correlate the two tanks until they
    // drifted apart.
    leftTank_.lfo.prepare  (static_cast<float> (kBaseSampleRate), 0xC0FFEEu);
    rightTank_.lfo.prepare (static_cast<float> (kBaseSampleRate), 0xBADBEEFu);
}

void SixAPTankEngine::prepare (double sampleRate, int maxBlockSize)
{
    sampleRate_ = sampleRate;

    // Pre-allocate scratch for the parallel-diffuser pass so the audio
    // thread never resizes a vector mid-process.
    diffusedL_.assign (static_cast<size_t> (std::max (maxBlockSize, 1)), 0.0f);
    diffusedR_.assign (static_cast<size_t> (std::max (maxBlockSize, 1)), 0.0f);

    auto setupTank = [sampleRate] (Tank& t,
                                    int ap1Base, int del1Base,
                                    int ap2Base, int del2Base,
                                    const int (&densBase)[kNumDensityAPs])
    {
        t.ap1BaseDelay   = ap1Base;
        t.delay1BaseDelay = del1Base;
        t.ap2BaseDelay   = ap2Base;
        t.delay2BaseDelay = del2Base;
        for (int i = 0; i < kNumDensityAPs; ++i)
            t.densityAPBase[i] = densBase[i];

        float rateRatio = static_cast<float> (sampleRate / kBaseSampleRate);
        int reserve = static_cast<int> (static_cast<float> (kMaxBaseDelay) * rateRatio + 64.0f);

        t.ap1Buffer.allocate (reserve);
        t.delay1   .allocate (reserve);
        t.ap2      .allocate (reserve);
        t.delay2   .allocate (reserve);
        // Density-AP buffers must allow for the maximum sizeScale so the
        // delay can grow with the size knob; previously they were sized for
        // 1.0× only, which forced updateDelayLengths() to leave them
        // un-scaled (and produced a permanent ~44 ms diffusion path that
        // dominated the loop at low size, sounding like a discrete delay).
        constexpr float kMaxSizeScale = 1.5f;
        for (int i = 0; i < kNumDensityAPs; ++i)
        {
            t.densityAP[i].allocate (static_cast<int> (
                static_cast<float> (densBase[i]) * rateRatio * kMaxSizeScale + 16.0f));
            // Sub-audio (1.5 Hz) density-AP jitter — mirrors DattorroTank/
            // QuadTank fix. Audio-band variant produced #87 vibrato/bell;
            // slow random-walk wander breaks comb-tooth phase-lock on Hall/
            // Ambient presets without sidebands. 3 % depth.
            t.densityAP[i].jitterDepthFraction = 0.03f;
        }

        t.damping.prepare (static_cast<float> (sampleRate));
        // Initial 3-band coefficients: gLow / gMid / gHigh + low/high crossover
        // coefficients (exp(-2π·fc/sr)). Will be overwritten by the first
        // updateDecayCoefficients() call.
        t.damping.setCoefficients (0.99f, 0.95f, 0.5f, 0.95f, 0.6f);
    };

    setupTank (leftTank_,  kLeftAP1Base,  kLeftDel1Base,  kLeftAP2Base,  kLeftDel2Base,  kLeftDensityAPBase);
    setupTank (rightTank_, kRightAP1Base, kRightDel1Base, kRightAP2Base, kRightDel2Base, kRightDensityAPBase);

    // Distinct LFO seeds per density AP (and per L/R tank) so the random
    // walks never align — every AP wanders independently. The LFO RATE is
    // not set here; updateJitterDepth() (called from updateDelayLengths
    // below) computes a per-AP rate based on the AP's current delay so the
    // LFO period is ~2× the ring period — fast enough to break short rings,
    // slow enough to stay below audibility for long rings.
    for (int i = 0; i < kNumDensityAPs; ++i)
    {
        const std::uint32_t lSeed = 0xBADBEEFu + static_cast<std::uint32_t> (i * 31337);
        const std::uint32_t rSeed = 0xC0FFEEu  + static_cast<std::uint32_t> (i * 27449);
        leftTank_ .densityAP[i].jitterLFO.prepare (static_cast<float> (sampleRate), lSeed);
        rightTank_.densityAP[i].jitterLFO.prepare (static_cast<float> (sampleRate), rSeed);
    }

    // Re-seed LFOs at the actual host sample rate so smoothing/period
    // calculations are correct.
    leftTank_.lfo.prepare  (static_cast<float> (sampleRate), 0xC0FFEEu);
    rightTank_.lfo.prepare (static_cast<float> (sampleRate), 0xBADBEEFu);


    updateDelayLengths();
    updateDecayCoefficients();
    updateLFORates();
    setModDepth (lastModDepthRaw_);   // re-pushes depth to the new-rate-aware LFOs

    parallelDiffuser_.prepare (sampleRate);

    prepared_ = true;
}

void SixAPTankEngine::clearBuffers()
{
    auto clearTank = [] (Tank& t)
    {
        t.ap1Buffer.clear();
        t.delay1.clear();
        t.delay2.clear();
        t.ap2.clear();
        for (int i = 0; i < kNumDensityAPs; ++i)
            t.densityAP[i].clear();
        t.damping.reset();
        t.crossFeedState = 0.0f;
    };
    clearTank (leftTank_);
    clearTank (rightTank_);
    parallelDiffuser_.clear();
}

void SixAPTankEngine::setDecayTime (float seconds)
{
    // Knob-honesty calibration (2026-05-31). Raw figure-8 decay law is sub-unity
    // and nonlinear: measured mid-band RT60 ≈ 0.9799·T^0.8087 at nominal size.
    // Invert it so the displayed Decay knob reads true RT60 seconds across the
    // musical range. internal = (R/C)^(1/P) feeds the existing coefficient math.
    const float honest = std::max (0.05f, seconds);
    decayTime_ = std::clamp (std::pow (honest / 0.9799f, 1.0f / 0.8087f), 0.05f, 60.0f);
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::setBassMultiply (float mult)
{
    bassMultiply_ = std::clamp (mult, 0.1f, 4.0f);
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::setMidMultiply (float mult)
{
    midMultiply_ = std::clamp (mult, 0.1f, 4.0f);
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::setTrebleMultiply (float mult)
{
    trebleMultiply_ = std::clamp (mult, 0.05f, 4.0f);
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::setCrossoverFreq (float hz)
{
    crossoverFreq_ = std::clamp (hz, 100.0f, 8000.0f);
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::setHighCrossoverFreq (float hz)
{
    // Clamp above the low crossover so the two filters don't invert.
    highCrossoverFreq_ = std::clamp (hz, std::max (crossoverFreq_ + 100.0f, 1000.0f), 12000.0f);
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::setSaturation (float amount)
{
    saturationAmount_ = std::clamp (amount, 0.0f, 1.0f);
}

void SixAPTankEngine::setModDepth (float depth)
{
    lastModDepthRaw_ = std::clamp (depth, 0.0f, 1.0f);
    float rateRatio = static_cast<float> (sampleRate_ / kBaseSampleRate);
    // Normalised across all four engines: depth × 16 samples peak at 44.1 k.
    // (Was 8 — half the others — which made the same knob position feel
    // weaker on this engine than on Dattorro/QuadTank/FDN.)
    modDepthSamples_ = lastModDepthRaw_ * 16.0f * rateRatio;
    leftTank_.lfo.setDepth  (modDepthSamples_);
    rightTank_.lfo.setDepth (modDepthSamples_);
}

void SixAPTankEngine::setModRate (float hz)
{
    modRateHz_ = std::clamp (hz, 0.05f, 12.0f);
    if (prepared_)
        updateLFORates();
}

void SixAPTankEngine::setSize (float size)
{
    sizeParam_ = std::clamp (size, 0.0f, 1.0f);
    if (prepared_)
    {
        updateDelayLengths();
        updateDecayCoefficients();
    }
}

void SixAPTankEngine::setTankDiffusion (float amount)
{
    // knob 0 → 0.5×, knob 0.5 → 1.0×, knob 0.85 (typical preset) → 1.095×,
    // knob 1.0 → 1.2×. Capped at bloomCoeffCeiling_ absolute for AP stability.
    float a = std::clamp (amount, 0.0f, 1.0f);
    lastTankDiffusionAmount_ = a;
    float scale = 0.5f + a * 0.7f;
    densityDiffCoeff_ = std::clamp (densityDiffBaseline_ * scale, 0.0f, bloomCoeffCeiling_);
}

void SixAPTankEngine::setDensityBaseline (float v)
{
    densityDiffBaseline_ = std::clamp (v, 0.30f, 0.90f);
    // Re-apply the diffusion-knob scaling around the new baseline so the
    // user-facing knob continues to behave consistently.
    setTankDiffusion (lastTankDiffusionAmount_);
}

void SixAPTankEngine::setBloomCeiling (float v)
{
    bloomCoeffCeiling_ = std::clamp (v, 0.70f, 0.95f);
    // Re-apply the diffusion-knob scaling so densityDiffCoeff_ respects the
    // new ceiling on the working coefficient as well.
    setTankDiffusion (lastTankDiffusionAmount_);
}

void SixAPTankEngine::setBloomStagger (const float values[6])
{
    for (int i = 0; i < kNumDensityAPs; ++i)
        bloomStagger_[i] = std::clamp (values[i], 0.0f, 2.0f);
}

void SixAPTankEngine::setEarlyMix (float v)
{
    earlyMix_ = std::clamp (v, 0.0f, 1.5f);
}

void SixAPTankEngine::setOutputTrim (float v)
{
    outputTrim_ = std::clamp (v, 0.5f, 2.0f);
}

void SixAPTankEngine::setFreeze (bool frozen)
{
    frozen_ = frozen;
    if (prepared_)
        updateDecayCoefficients();
}

void SixAPTankEngine::updateDelayLengths()
{
    // Size knob spans 0.2× to 1.5× of the baked tank delays. The minimum
    // 0.2× was 0.5× before; at the bottom of the range the loop is now
    // ~37 ms instead of ~114 ms, which lets the user dial in a genuine
    // tight room rather than a discrete ~10 Hz delay.
    float sizeScale = 0.2f + sizeParam_ * 1.3f;
    float rateRatio = static_cast<float> (sampleRate_ / kBaseSampleRate);

    auto setTankDelays = [&] (Tank& t)
    {
        t.ap1DelaySamples = static_cast<float> (t.ap1BaseDelay) * sizeScale * rateRatio;
        t.delay1Samples   = static_cast<float> (t.delay1BaseDelay) * sizeScale * rateRatio;
        t.delay2Samples   = static_cast<float> (t.delay2BaseDelay) * sizeScale * rateRatio;

        t.ap2.delaySamples = std::min (
            static_cast<int> (static_cast<float> (t.ap2BaseDelay) * sizeScale * rateRatio),
            t.ap2.mask);

        // Density APs scale with size too (matching DattorroTank). Without
        // this, the 6-stage density cascade contributes a fixed ~44 ms path
        // through the loop at every size setting — at low size that fixed
        // delay dominates and the loop reads as a discrete echo rather than
        // a reverb wash. After updating delaySamples we MUST refresh the
        // jitter LFO (depth + rate) so the spin-and-wander modulation tracks
        // the new delay length — otherwise the largest APs at hall sizes
        // ring audibly because their relative jitter shrinks AND a slow
        // LFO can't break their short ring period.
        const float sr = static_cast<float> (sampleRate_);
        for (int i = 0; i < kNumDensityAPs; ++i)
        {
            t.densityAP[i].delaySamples = std::min (
                static_cast<int> (static_cast<float> (t.densityAPBase[i])
                                  * sizeScale * rateRatio),
                t.densityAP[i].mask);
            t.densityAP[i].updateJitterDepth (sr);
        }
    };

    setTankDelays (leftTank_);
    setTankDelays (rightTank_);
}

void SixAPTankEngine::updateDecayCoefficients()
{
    if (frozen_)
    {
        // 3-band: gLow / gMid / gHigh, lowXover / highXover coeffs.
        // Frozen = unity at every band, no shelving.
        leftTank_.damping.setCoefficients (1.0f, 1.0f, 1.0f, 0.0f, 0.0f);
        rightTank_.damping.setCoefficients (1.0f, 1.0f, 1.0f, 0.0f, 0.0f);
        return;
    }

    // Per-tank Sabine: g_loop = exp(-3 ln10 · loopLen / (sr · RT60)).
    //
    // Effective loop length = direct delays (ap1/delay1/ap2/delay2) PLUS the
    // sum of density-AP delays PLUS an empirical compensation for energy
    // stored *inside* each density AP. The compensation factor is NOT
    // constant — it depends on size:
    //   • At small size, the direct loop is short relative to the density
    //     cascade. The cascade's energy storage dominates the actual decay,
    //     so a large factor is needed to make the formula match.
    //   • At large size, the direct loop is long. Density storage matters
    //     proportionally less. Using the small-size factor over-compensates,
    //     producing too-fast decay (verified: factor 2.10 at size=0.95 gave
    //     5.84 s actual vs 6.5 s target = 10 % short).
    //
    // Empirical linear interpolation: factor = 2.10 at size=0.5, 1.55 at
    // size=1.0. Equivalent: 2.65 - 1.10·size.
    //   Calibrated against render-tool RT60 measurements at size=0.75
    //   (Lush Dark Hall) and size=0.95 (Cathedral / Blade Runner 224).
    //   We tried 2.45 to compensate for a +5-15 % systematic over-shoot,
    //   but that was measured BEFORE the input-diffuser jitter (which
    //   adds wider smear and itself extends measured RT60 by a few %).
    //   With both fixes active, 2.65 lands closer to UI target.
    const float storageFactor = 2.65f - 1.10f * sizeParam_;
    auto loopLen = [storageFactor] (const Tank& t) {
        float densityLen = 0.0f;
        for (int i = 0; i < kNumDensityAPs; ++i)
            densityLen += static_cast<float> (t.densityAP[i].delaySamples);
        const float densityEffective = densityLen * storageFactor;
        return static_cast<float> (t.ap1DelaySamples + t.delay1Samples
                                   + t.ap2.delaySamples + t.delay2Samples)
             + densityEffective;
    };

    float numerator = -3.0f * 2.302585092994046f / static_cast<float> (sampleRate_);

    // Hard ceiling on per-band loop gain — guarantees the cross-coupled tank
    // pair is provably stable even at decay = 30 s + bass-mult = 2.5. Ceiling
    // 0.98 corresponds to a worst-case RT60 of ~24 s at our typical loop
    // lengths, which is musically indistinguishable from longer settings but
    // mathematically prevents self-oscillation.
    constexpr float kMaxBandGain = 0.98f;
    auto bandGain = [numerator, kMaxBandGain, this] (float loopSamples, float multiplier) {
        float effRt60 = std::max (decayTime_ * multiplier, 0.05f);
        return std::clamp (std::exp (numerator * loopSamples / effRt60), 0.0f, kMaxBandGain);
    };

    auto lowXoverCoeff  = std::exp (-kTwoPi * crossoverFreq_     / static_cast<float> (sampleRate_));
    auto highXoverCoeff = std::exp (-kTwoPi * highCrossoverFreq_ / static_cast<float> (sampleRate_));

    auto applyToTank = [&] (Tank& t)
    {
        float L = loopLen (t);
        float gLow = bandGain (L, bassMultiply_);
        float gMid = bandGain (L, midMultiply_);
        float gHi  = bandGain (L, trebleMultiply_);
        // 3-band shelving damping (matches Dattorro / QuadTank / FDN topology).
        // Pass ABSOLUTE per-band gains; the ThreeBandDamping internally derives
        // shelf gains relative to gMid (broadband multiplier).
        t.damping.setCoefficients (gLow, gMid, gHi, lowXoverCoeff, highXoverCoeff);
    };
    applyToTank (leftTank_);
    applyToTank (rightTank_);
}

void SixAPTankEngine::updateLFORates()
{
    // Tightly clustered L/R spread (0.98×/1.02×). Previous 1.0/1.13×
    // (13 %) trimmed to match the global engine-wide de-chorus policy.
    // Distinct PRNG seeds keep per-sample variance to avoid phase-lock.
    leftTank_.lfo.setRate  (modRateHz_ * 0.98f);
    rightTank_.lfo.setRate (modRateHz_ * 1.02f);
}

void SixAPTankEngine::process (const float* inputL, const float* inputR,
                                 float* outputL, float* outputR, int numSamples)
{
    if (! prepared_)
    {
        std::memset (outputL, 0, sizeof (float) * static_cast<size_t> (numSamples));
        std::memset (outputR, 0, sizeof (float) * static_cast<size_t> (numSamples));
        return;
    }

    // Drive-style saturation (see DattorroTank for rationale).
    const float satThreshold = 1.0f - saturationAmount_ * 0.6f;
    const float satCeiling   = 2.0f;

    // ---- BLOOM stagger (now per-instance via bloomStagger_ / bloomCoeffCeiling_) ----
    // Earlier stages run gentler (more transient spread), later stages bite
    // harder (more late-tail ring). Each effective coefficient is hard-
    // clamped to bloomCoeffCeiling_ so even the largest late-stage
    // multiplier × densityDiffCoeff_ cannot push an AP toward self-
    // oscillation. Defaults preserve the historical {0.7..1.2}/0.85 values;
    // Black Hole opts in to a steeper stagger + higher ceiling for VS
    // BlackHole-character late-tail density.

    // ---- Step 0: shatter the input through the parallel diffuser ----
    // The 6-AP-specific input shatter replaces the global series diffuser
    // (bypassed for this engine in DuskVerbEngine::process). After this
    // pass, inL/inR samples carry ~40 dense reflections per channel from
    // the parallel-AP sum — enough density that the tank's 6-AP cascade
    // never sees a sharp transient and the listener never hears a discrete
    // echo cluster. We diffuse into scratch members (the input pointers
    // are const) so we don't mutate the caller's buffer; scratch is
    // pre-sized in prepare() so the audio thread does not allocate.
    const int diffuseN = std::min (numSamples, static_cast<int> (diffusedL_.size()));
    std::memcpy (diffusedL_.data(), inputL, sizeof (float) * static_cast<size_t> (diffuseN));
    std::memcpy (diffusedR_.data(), inputR, sizeof (float) * static_cast<size_t> (diffuseN));
    parallelDiffuser_.process (diffusedL_.data(), diffusedR_.data(), diffuseN);

    const float* in_L = diffusedL_.data();
    const float* in_R = diffusedR_.data();

    // Iterate ONLY over the scratch-buffer-valid range. diffuseN caps reads of
    // in_L/in_R and diffusedL_/diffusedR_ (earlyL/earlyR) to the prepared size;
    // a host block larger than maxBlockSize would otherwise read out of bounds.
    for (int n = 0; n < diffuseN; ++n)
    {
        float inL = in_L[n];
        float inR = in_R[n];

        // ---- LEFT TANK ----
        // Random-walk LFO: smoothed-noise modulation of the AP1 read head.
        // Replaces the previous std::sin(phase) LFO so the modulation never
        // beats periodically against the tank's modal frequencies — gives
        // the "expensive shimmer" of high-end random-hall hardware.
        const float lfoMod = leftTank_.lfo.next();
        float ap1Read = leftTank_.ap1Buffer.readInterpolated (
            std::clamp (leftTank_.ap1DelaySamples + lfoMod, 1.0f,
                        static_cast<float> (leftTank_.ap1Buffer.mask)));
        float ap1In = inL + leftTank_.crossFeedState - decayDiff1_ * ap1Read;
        leftTank_.ap1Buffer.write (ap1In);
        float postAP1 = ap1Read + decayDiff1_ * ap1In;

        leftTank_.delay1.write (postAP1);
        float del1 = leftTank_.delay1.read (static_cast<int> (leftTank_.delay1Samples));

        float density = del1;
        for (int i = 0; i < kNumDensityAPs; ++i)
        {
            const float coeff = std::min (densityDiffCoeff_ * bloomStagger_[i],
                                          bloomCoeffCeiling_);
            density = leftTank_.densityAP[i].process (density, coeff);
        }

        float damped = leftTank_.damping.process (density);
        float ap2Out = leftTank_.ap2.process (damped, decayDiff2_);
        leftTank_.delay2.write (ap2Out);
        float leftLoop = leftTank_.delay2.read (static_cast<int> (leftTank_.delay2Samples));

        // ---- RIGHT TANK ----
        const float lfoModR = rightTank_.lfo.next();
        float ap1ReadR = rightTank_.ap1Buffer.readInterpolated (
            std::clamp (rightTank_.ap1DelaySamples + lfoModR, 1.0f,
                        static_cast<float> (rightTank_.ap1Buffer.mask)));
        float ap1InR = inR + rightTank_.crossFeedState - decayDiff1_ * ap1ReadR;
        rightTank_.ap1Buffer.write (ap1InR);
        float postAP1R = ap1ReadR + decayDiff1_ * ap1InR;

        rightTank_.delay1.write (postAP1R);
        float del1R = rightTank_.delay1.read (static_cast<int> (rightTank_.delay1Samples));

        float densityR = del1R;
        for (int i = 0; i < kNumDensityAPs; ++i)
        {
            const float coeff = std::min (densityDiffCoeff_ * bloomStagger_[i],
                                          bloomCoeffCeiling_);
            densityR = rightTank_.densityAP[i].process (densityR, coeff);
        }

        float dampedR = rightTank_.damping.process (densityR);
        float ap2OutR = rightTank_.ap2.process (dampedR, decayDiff2_);
        rightTank_.delay2.write (ap2OutR);
        float rightLoop = rightTank_.delay2.read (static_cast<int> (rightTank_.delay2Samples));

        // Cross-feed: each tank's loop output feeds the OTHER tank's input.
        // Two protections layered on the write:
        //   • softClip — analog-style soft saturation that engages only above
        //     ±1.0, adds harmonic warmth on transients without altering RT60
        //     of quiet tail samples;
        //   • alternating-sign denormal bias to prevent the loop from
        //     collapsing into denormalised floats (CPU-spike protection).
        //
        // MÖBIUS TWIST: the right-tank cross-feed is sign-inverted on the
        // write so the two tanks anti-correlate forever. Without this, an
        // 18-second tail eventually drifts toward mono as the left-into-
        // right and right-into-left feedback paths converge. Negating one
        // path turns the loop into a true 180° figure-8 — every recirc
        // flips polarity, mathematically guaranteed not to converge.
        const float l = DspUtils::softClip (rightLoop, satThreshold, satCeiling);
        const float r = DspUtils::softClip (leftLoop,  satThreshold, satCeiling);
        leftTank_.crossFeedState  = std::clamp ( l, -kSafetyClip, kSafetyClip)
                                  + DspUtils::kDenormalPrevention;
        rightTank_.crossFeedState = std::clamp (-r, -kSafetyClip, kSafetyClip)
                                  - DspUtils::kDenormalPrevention;

        // STEREO BIND: each output channel mixes its own tank's post-cascade
        // `damped` signal (primary) with a phase-inverted ½-amplitude slice
        // of the OPPOSITE tank's loop output. Without this, hard-panned
        // input material produces lopsided reverb (only one tank gets fed,
        // only one channel rings). The phase-inverted cross-mix guarantees
        // both output channels carry signal regardless of input panning,
        // and the inversion preserves the MöbiusTwist anti-correlation —
        // the cross terms partially cancel in mono so a mono sum stays
        // close to the dry-mid character rather than doubling.
        //
        // 2.0 → 1.3 trim because the cross-mix adds ~+4 dB of summed
        // energy on hard-mono input and we need to stay under unity ceiling.
        //
        // EARLY-FILL: mix the ParallelDiffuser's output directly into the
        // audio output. The cascade output (damped/dampedR) is mathematically
        // silent until the input has traversed delay1 (~90-140 ms depending
        // on size knob), so without this mix the listener perceives a long
        // dead period before any wet appears even at predelay = 0. The
        // ParallelDiffuser was producing dense AP-delay impulses (11, 16,
        // 23, 32, 45, 60 ms) the whole time but feeding only the tank input;
        // routing some of it to the output too gives instant early reflections
        // that bridge T+0 to T+~90 ms before the cascade tail kicks in.
        // EarlyMix and OutputTrim are now per-instance (earlyMix_ / outputTrim_)
        // so individual presets can opt in to brighter onsets / different
        // trim balance without affecting other presets sharing this engine.
        // Defaults preserve the historical 0.5 / 1.3 values.
        const float earlyL = diffusedL_[static_cast<size_t> (n)];
        const float earlyR = diffusedR_[static_cast<size_t> (n)];
        outputL[n] = (damped  + rightLoop * 0.5f + earlyL * earlyMix_) * outputTrim_;
        outputR[n] = (dampedR - leftLoop  * 0.5f + earlyR * earlyMix_) * outputTrim_;
    }

    // If the host block exceeded prepare()'s maxBlockSize, diffuseN capped the
    // processed range — clear the unprocessed tail rather than leave it stale.
    for (int n = diffuseN; n < numSamples; ++n) { outputL[n] = 0.0f; outputR[n] = 0.0f; }
}
// ---- plugins/DuskVerb/src/dsp/SpringEngine.cpp


namespace
{
    constexpr float kTwoPi_SpringEngine = 6.283185307179586f;

    // Per-spring base dispersion coefficient *magnitude*. The sign is always
    // negative (chirps with HF arriving later, the canonical 3-spring-unit character).
    // Slight per-spring variation gives the parallel sum its characteristic
    // shimmer instead of a coherent single-spring chirp.
    constexpr float kPerSpringChirpScale[3] = { 0.65f, 0.70f, 0.75f };
}

void SpringEngine::Spring::allocate (int maxSamples)
{
    const int size = DspUtils::nextPowerOf2 (std::max (maxSamples + 8, 64));
    delayBuf.assign (static_cast<size_t> (size), 0.0f);
    mask = size - 1;
    writePos = 0;
}

void SpringEngine::Spring::clear()
{
    std::fill (delayBuf.begin(), delayBuf.end(), 0.0f);
    writePos = 0;
    dampState = 0.0f;
    for (auto& ap : dispersionAPs)
        ap.clear();
}

float SpringEngine::Spring::process (float input, float lfoOffset) noexcept
{
    // 1) Read from delay line at the modulated position. lfoOffset is in
    //    samples (signed); linear interpolation for sub-sample positioning.
    const float readPosF = static_cast<float> (writePos)
                         - static_cast<float> (delaySamples)
                         - lfoOffset;
    const int   intIdx   = static_cast<int> (std::floor (readPosF));
    const float frac     = readPosF - static_cast<float> (intIdx);
    const int   idx0     = intIdx & mask;
    const int   idx1     = (intIdx + 1) & mask;
    const float read = delayBuf[static_cast<size_t> (idx0)] * (1.0f - frac)
                     + delayBuf[static_cast<size_t> (idx1)] *         frac;

    // 2) HF damping IN THE LOOP — 1-pole LP on the recirculating signal so the
    //    tail progressively darkens with every bounce (a real 3-spring outboard spring
    //    rolls off more HF on each pass, not just once at the output).
    dampState = (1.0f - dampCoeff) * read + dampCoeff * dampState;

    // 3) Dispersion cascade IN THE LOOP — 24 1st-order all-passes on the
    //    recirculating signal. Each pass adds more frequency-dependent group
    //    delay, so the chirp COMPOUNDS over the tail (the iconic spring
    //    "boinggg…boing…boing" train) instead of only the first reflection.
    float disp = dampState;
    for (auto& ap : dispersionAPs)
        disp = ap.process (disp, dispersionA);

    // 4) Write fresh input + the recirculated (damped + dispersed) energy
    //    (Karplus-Strong style). Feedback gain scales per-spring for matched RT60.
    const float bufIn = input + feedback * disp;
    delayBuf[static_cast<size_t> (writePos)] = bufIn + DspUtils::kDenormalPrevention;
    writePos = (writePos + 1) & mask;

    // The spring's voice is the damped + dispersed recirculating signal.
    return disp;
}

void SpringEngine::prepare (double sampleRate, int /*maxBlockSize*/)
{
    sampleRate_ = sampleRate;

    const float rateRatio = static_cast<float> (sampleRate / 44100.0);
    // Worst-case length = base × max-size-scale × rateRatio + LFO headroom.
    constexpr float kMaxSizeScale = 1.6f;     // clamp slightly above the normal 1.5×
    constexpr int   kLfoHeadroom  = 32;       // samples of room for LFO read-position offset

    auto setupSpring = [&] (Spring& s, int baseDelay, float chirpScale)
    {
        const int reserve = static_cast<int> (
            static_cast<float> (baseDelay) * kMaxSizeScale * rateRatio + kLfoHeadroom + 4.0f);
        s.allocate (reserve);
        s.dispersionA = -chirpAmount_ * chirpScale;
    };

    for (int i = 0; i < kNumSprings; ++i)
    {
        setupSpring (leftSprings_ [i], kLeftBaseDelays [i], kPerSpringChirpScale[i]);
        setupSpring (rightSprings_[i], kRightBaseDelays[i], kPerSpringChirpScale[i]);
    }

    // Independent random-walk LFOs per channel — the read-position wobble
    // that gives a real 3-spring tank its constantly-quivering character.
    lfoL_.prepare (static_cast<float> (sampleRate), 0xC0FFEEu);
    lfoR_.prepare (static_cast<float> (sampleRate), 0xBADBEEFu);

    updateSpringLengths();
    updateFeedback();
    updateDamping();
    updateDispersion();
    updateLFO();

    prepared_ = true;
}

void SpringEngine::clearBuffers()
{
    for (auto& s : leftSprings_)  s.clear();
    for (auto& s : rightSprings_) s.clear();
}

// ============================================================================
// Universal setters — each one updates the cached value, then re-runs the
// affected per-spring update. Cheap (~12 multiplications) so safe to call
// at parameter-change rate.
// ============================================================================

void SpringEngine::setDecayTime (float seconds)
{
    decayTime_ = std::max (0.05f, seconds);
    if (prepared_) updateFeedback();
}

void SpringEngine::setSize (float size)
{
    sizeParam_ = std::clamp (size, 0.0f, 1.0f);
    if (prepared_)
    {
        updateSpringLengths();
        updateFeedback();          // feedback depends on loop period
    }
}

void SpringEngine::setBassMultiply  (float mult) { bassMult_ = std::clamp (mult, 0.1f, 4.0f); }

// TODO: midMult_ is accepted for cross-engine setter parity but not yet wired
// into the spring tank. Implementing it requires a band-split (using
// crossoverHz_ / highCrossoverHz_) so the mid band can be scaled independently
// of bassMult_/trebleMult_. Until then this is a no-op cache.
void SpringEngine::setMidMultiply   (float mult) { midMult_  = std::clamp (mult, 0.1f, 4.0f); }

void SpringEngine::setTrebleMultiply (float mult)
{
    trebleMult_ = std::clamp (mult, 0.05f, 4.0f);
    if (prepared_) updateDamping();
}

// TODO: crossoverHz_ / highCrossoverHz_ are accepted for cross-engine setter
// parity. The spring tank currently uses a single 1-pole HF damper per spring
// (see updateDamping); proper multi-band damping driven by these crossovers
// would need filters added to Spring::process and corresponding update hooks.
void SpringEngine::setCrossoverFreq     (float hz) { crossoverHz_     = std::clamp (hz,  100.0f,  8000.0f); }
void SpringEngine::setHighCrossoverFreq (float hz) { highCrossoverHz_ = std::clamp (hz, 1000.0f, 12000.0f); }

void SpringEngine::setSaturation (float amount) { saturationAmount_ = std::clamp (amount, 0.0f, 1.0f); }

void SpringEngine::setModDepth (float depth)
{
    modDepthRaw_ = std::clamp (depth, 0.0f, 1.0f);
    if (prepared_) updateLFO();
}

void SpringEngine::setModRate (float hz)
{
    modRateRaw_ = std::clamp (hz, 0.05f, 12.0f);
    if (prepared_) updateLFO();
}

void SpringEngine::setTankDiffusion (float amount)
{
    chirpAmount_ = std::clamp (amount, 0.0f, 1.0f);
    if (prepared_) updateDispersion();
}

void SpringEngine::setFreeze (bool frozen)
{
    frozen_ = frozen;
    if (prepared_) updateFeedback();
}

// ============================================================================
// Update helpers
// ============================================================================

void SpringEngine::updateSpringLengths()
{
    // size 0 → 0.5×, size 1 → 1.5×. Same shape as the other engines'
    // size-scale curve so users get consistent muscle memory.
    const float sizeScale = 0.5f + sizeParam_ * 1.0f;
    const float rateRatio = static_cast<float> (sampleRate_ / 44100.0);

    for (int i = 0; i < kNumSprings; ++i)
    {
        leftSprings_ [i].delaySamples = std::min (
            static_cast<int> (static_cast<float> (kLeftBaseDelays [i]) * sizeScale * rateRatio),
            leftSprings_ [i].mask - 8);
        rightSprings_[i].delaySamples = std::min (
            static_cast<int> (static_cast<float> (kRightBaseDelays[i]) * sizeScale * rateRatio),
            rightSprings_[i].mask - 8);
    }
}

void SpringEngine::updateFeedback()
{
    // Per-spring feedback to hit the requested RT60 across all 3 springs
    // (different lengths → different feedback values for matched decay).
    //   gain^N = 10^(-60/20)   where N = RT60 / loopPeriod
    //   gain   = 10^(-3 × loopPeriod / RT60)
    // Freeze pins feedback at 1.0 for infinite sustain.
    auto computeFb = [this] (int delaySamples) -> float
    {
        if (frozen_) return 1.0f;
        const float loopPeriod = static_cast<float> (delaySamples) / static_cast<float> (sampleRate_);
        const float fb = std::pow (10.0f, -3.0f * loopPeriod / std::max (decayTime_, 0.05f));
        return std::clamp (fb, 0.0f, 0.97f);   // hard cap below 1.0 for stability
    };

    for (int i = 0; i < kNumSprings; ++i)
    {
        leftSprings_ [i].feedback = computeFb (leftSprings_ [i].delaySamples);
        rightSprings_[i].feedback = computeFb (rightSprings_[i].delaySamples);
    }
}

void SpringEngine::updateDamping()
{
    // trebleMult = 1.0  → fc ≈ 5000 Hz (canonical tube-amp spring rolloff)
    // trebleMult = 0.1  → fc ≈ 500 Hz  (very dark)
    // trebleMult = 1.5  → fc ≈ 7500 Hz (open / bright)
    const float fc = std::clamp (5000.0f * trebleMult_, 200.0f,
                                 0.4f * static_cast<float> (sampleRate_));
    const float coeff = std::exp (-kTwoPi_SpringEngine * fc / static_cast<float> (sampleRate_));

    for (auto& s : leftSprings_)  s.dampCoeff = coeff;
    for (auto& s : rightSprings_) s.dampCoeff = coeff;
}

void SpringEngine::updateDispersion()
{
    // chirpAmount 0 → a = 0 (no dispersion → plain delay-with-feedback).
    // chirpAmount 1 → a = -0.85 × per-spring scale (full chirp).
    // Per-spring scale (0.65, 0.70, 0.75) gives each spring a slightly
    // different chirp shape so the summed output has natural variation.
    constexpr float kMaxA = 0.85f;
    for (int i = 0; i < kNumSprings; ++i)
    {
        const float a = -chirpAmount_ * kMaxA * kPerSpringChirpScale[i];
        leftSprings_ [i].dispersionA = a;
        rightSprings_[i].dispersionA = a;
    }
}

void SpringEngine::updateLFO()
{
    // LFO rate range: 0.1 Hz (slow shimmer) to 12 Hz (fast warble).
    // Depth in samples: modDepthRaw 0..1 → 0..6 sample peak excursion.
    // 6 samples ≈ ±0.13 ms at 48k → subtle "drip" without audible pitch shift.
    const float rateHz = modRateRaw_;
    const float depthSamples = modDepthRaw_ * 6.0f;
    lfoL_.setRate (rateHz);
    lfoR_.setRate (rateHz * 1.13f);    // small offset — independent L/R drift
    lfoL_.setDepth (depthSamples);
    lfoR_.setDepth (depthSamples);
}

// ============================================================================
// Process
// ============================================================================

void SpringEngine::process (const float* inL, const float* inR,
                            float* outL, float* outR, int numSamples)
{
    if (! prepared_)
    {
        std::memset (outL, 0, sizeof (float) * static_cast<size_t> (numSamples));
        std::memset (outR, 0, sizeof (float) * static_cast<size_t> (numSamples));
        return;
    }

    // Drive-style soft clip on input — matches the saturation knob on the
    // other engines. Subtle harmonic warmth on hot transients.
    const float satThreshold = 1.0f - saturationAmount_ * 0.6f;
    const float satCeiling   = 2.0f;

    // Energy normalisation across the 3 parallel springs (sum amplitude
    // scales as √N for uncorrelated signals; alternating polarity prevents
    // comb-filtering when all 3 fire at the impulse moment).
    constexpr float kSpringNorm = 0.57735026919f;   // 1/√3
    constexpr float kSpringPolarity[3] = { +1.0f, -1.0f, +1.0f };

    // Bass post-shelf — extremely cheap 1-shelf approximation: just scale
    // the output. Real bass shelving would need a 1-pole LF filter, but
    // for a spring tank a flat low-end multiplier is character-correct
    // (no interaction with the spring's own resonance which lives mid-band).
    const float bassPostGain = bassMult_;

    for (int n = 0; n < numSamples; ++n)
    {
        const float lfoOffsetL = lfoL_.next();
        const float lfoOffsetR = lfoR_.next();

        const float xL = DspUtils::softClip (inL[n], satThreshold, satCeiling);
        const float xR = DspUtils::softClip (inR[n], satThreshold, satCeiling);

        float sumL = 0.0f, sumR = 0.0f;
        for (int i = 0; i < kNumSprings; ++i)
        {
            sumL += kSpringPolarity[i] * leftSprings_ [i].process (xL, lfoOffsetL);
            sumR += kSpringPolarity[i] * rightSprings_[i].process (xR, lfoOffsetR);
        }

        outL[n] = sumL * kSpringNorm * bassPostGain;
        outR[n] = sumR * kSpringNorm * bassPostGain;
    }
}
